static int compare64(const void*a,const void*b){int64_t x=*(int64_t*)a,y=*(int64_t*)b;return (x>y)-(x<y);}
int ui_benchmark(const wchar_t*dir,int count){int existing=count<0;if(existing)count=-count;DB d;if(!db_open(&d,dir))return 1;J*state=cJSON_CreateObject();sn(state,"version",2);const char*names[]={"tasks","notes","projects","tags","places"};for(int i=0;i<5;i++)set(state,names[i],cJSON_CreateArray());char*first=0;for(int i=0;i<(existing?0:count);i++){J*t=task_default(&d,i%4,0);char title[100];sprintf(title,"性能验收 Alpha 中文 %d",i);ss(t,"title",title);sn(t,"order",i*1024.);ss(t,"start",i%2?"2026-10-21T09:00":"");set(t,"subtasks",cJSON_CreateArray());if(!i)first=make_key("tasks",str(t,"id"));cJSON_AddItemToArray(get(state,"tasks"),t);}int64_t start=clock_us();int ok=(existing||db_import(&d,state))&&ui_query_init(&d);if(existing){sqlite3_stmt*s=0;sqlite3_prepare_v2(d.sql,"SELECT key FROM entities WHERE kind='tasks' AND deleted=0 LIMIT 1",-1,&s,0);if(sqlite3_step(s)==SQLITE_ROW)first=_strdup((char*)sqlite3_column_text(s,0));sqlite3_finalize(s);}cJSON_Delete(state);if(!ok){fprintf(stderr,"%s\n",d.error);db_close(&d);return 1;}int64_t importus=clock_us()-start;Filter f={0};strcpy(f.kind,"tasks");strcpy(f.date,"2026-10-21");f.status=2;f.period=3;f.quadrant=0;f.manual=1;int iterations=count>10000?5:40;int64_t samples[5][40];for(int i=0;i<iterations;i++){start=clock_us();for(int q=0;q<4;q++){f.quadrant=q;query_count(&d,&f);J*a=query_rows(&d,&f,0,32);cJSON_Delete(a);}samples[0][i]=clock_us()-start;start=clock_us();strcpy(f.kind,"search");f.quadrant=-1;strcpy(f.query,"Alpha 中文");query_count(&d,&f);J*a=query_rows(&d,&f,0,96);cJSON_Delete(a);samples[1][i]=clock_us()-start;f.query[0]=0;strcpy(f.kind,"tasks");f.quadrant=0;start=clock_us();J*r=db_row(&d,first);cJSON_Delete(r);samples[2][i]=clock_us()-start;start=clock_us();op_step(&d,first,i%2?1:-1);samples[3][i]=clock_us()-start;start=clock_us();a=query_rows(&d,&f,max(0,count/8-48),96);cJSON_Delete(a);samples[4][i]=clock_us()-start;}PROCESS_MEMORY_COUNTERS_EX memory={sizeof(memory)};GetProcessMemoryInfo(GetCurrentProcess(),(PROCESS_MEMORY_COUNTERS*)&memory,sizeof(memory));printf("{\"tasks\":%d,\"importAndIndexesMs\":%.3f,\"workingSetMiB\":%.3f,\"privateMiB\":%.3f,\"operations\":{",count,importus/1000.,memory.WorkingSetSize/1048576.,memory.PrivateUsage/1048576.);const char*op[]={"boardRefresh","keywordSearch","detailRead","siblingReorder","middlePage"};for(int n=0;n<5;n++){qsort(samples[n],iterations,sizeof(int64_t),compare64);printf("%s\"%s\":{\"p50Ms\":%.3f,\"p95Ms\":%.3f}",n?",":"",op[n],samples[n][iterations/2]/1000.,samples[n][(iterations-1)*95/100]/1000.);}printf("}}\n");free(first);db_close(&d);return 0;}
